"""Formula allow-list. Formulas are generated by code from templates (never by the model); this policy is a
second, independent check: only whitelisted functions, same-workbook refs, no external links, no names/macros."""
import re

ALLOWED_FUNCS = {"COUNT", "COUNTA", "SUM", "AVERAGE", "MIN", "MAX", "IF", "IFERROR", "COUNTIF", "COUNTIFS",
                 "SUMIF", "SUMIFS", "AVERAGEIF", "AVERAGEIFS", "MINIFS", "MAXIFS", "SUMPRODUCT", "ROUND"}
XLFN_FUNCS = {"MINIFS", "MAXIFS"}  # newer functions must carry the _xlfn. prefix inside .xlsx files
MAX_FORMULA_LEN = 2000
MAX_STRING_LITERAL = 255


class FormulaError(ValueError):
    pass


_TOKEN = re.compile(r"""
    (?P<str>"(?:[^"]|"")*")
  | (?P<sheet>'(?:[^']|'')+'!)
  | (?P<func>(?:_xlfn\.)?[A-Z][A-Z0-9.]*)\(
  | (?P<ref>\$?[A-Z]{1,3}\$?\d{1,7}(?::\$?[A-Z]{1,3}\$?\d{1,7})?)
  | (?P<num>\d+(?:\.\d+)?)
  | (?P<op><=|>=|<>|[-+*/<>=&,:])
  | (?P<open>\()
  | (?P<close>\))
  | (?P<ws>\s+)
""", re.X)
_CELL = re.compile(r"\$?([A-Z]{1,3})\$?(\d+)")


def _col_num(letters: str) -> int:
    n = 0
    for ch in letters:
        n = n * 26 + ord(ch) - 64
    return n


def validate_formula(formula: str, sheet_names: set[str]) -> None:
    """Raise FormulaError unless the formula satisfies the policy."""
    if not isinstance(formula, str) or not formula.startswith("="):
        raise FormulaError("not a formula")
    body = formula[1:]
    if not body or len(formula) > MAX_FORMULA_LEN:
        raise FormulaError("empty or too long")
    pos, depth, expect_ref = 0, 0, False
    while pos < len(body):
        m = _TOKEN.match(body, pos)
        if not m:
            raise FormulaError(f"disallowed character at {pos}")
        kind, text = m.lastgroup, m.group()
        pos = m.end()
        if expect_ref and kind != "ref":
            raise FormulaError("sheet prefix must precede a cell reference")
        expect_ref = False
        if kind == "str":
            if len(text) - 2 > MAX_STRING_LITERAL * 2:
                raise FormulaError("string literal too long")
        elif kind == "sheet":
            if text[1:-2].replace("''", "'") not in sheet_names:
                raise FormulaError("reference to unknown or external sheet")
            expect_ref = True
        elif kind == "func":
            name = m.group("func")
            base = name.removeprefix("_xlfn.")
            if base not in ALLOWED_FUNCS or (name != base and base not in XLFN_FUNCS):
                raise FormulaError(f"function not allowed: {name}")
            depth += 1
        elif kind == "open":
            depth += 1
        elif kind == "close":
            depth -= 1
            if depth < 0:
                raise FormulaError("unbalanced parentheses")
        elif kind == "ref":
            for col, row in _CELL.findall(text):
                if _col_num(col) > 16384 or not 1 <= int(row) <= 1_048_576:
                    raise FormulaError("cell reference out of range")
    if depth != 0 or expect_ref:
        raise FormulaError("unbalanced parentheses")
